'use client';
import {useEffect,useRef,useState} from 'react';
import {useClientReady} from '@/lib/client-ready';
import {hotelRpc,formText,cents,usd,type Booking,type RoomType} from '@/lib/pilot';
import {bookingStorageKey,readManualBooking,definitiveBookingRejection,type ManualBookingRequest} from '@/lib/pending-booking';
type Props={tenant:string;property:string;actor:string;types:RoomType[];businessDate:string;onBusyChange:(busy:boolean)=>void;onSaved:(booking:Booking)=>Promise<void>;onUseRates:()=>void};
export function ManualReservation(props:Props){const ready=useClientReady();return ready?<ManualForm {...props}/>:<p>Loading saved requests…</p>}
function ManualForm({tenant,property,actor,types,businessDate,onBusyChange,onSaved,onUseRates}:Props){
 const storageKey=bookingStorageKey('manual',actor,tenant,property);
 const [restored]=useState(()=>{try{return {pending:readManualBooking(storageKey),error:''}}catch(e){return {pending:null,error:e instanceof Error?e.message:'Unable to read the saved booking request.'}}});
 const [pending,setPending]=useState<ManualBookingRequest|null>(restored.pending),[error,setError]=useState(''),[busy,setBusy]=useState(false);const restoreError=restored.error,lock=useRef(false),alive=useRef(true);
 useEffect(()=>{alive.current=true;return()=>{alive.current=false;if(lock.current)onBusyChange(false)}},[onBusyChange]);
 async function run(fn:()=>Promise<void>){if(lock.current)return;lock.current=true;setBusy(true);onBusyChange(true);setError('');try{await fn()}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to save this reservation.')}finally{lock.current=false;if(alive.current){setBusy(false);onBusyChange(false)}}}
 async function book(command:ManualBookingRequest){
  let result:Booking;
  try{result=await hotelRpc<Booking>('create_reservation',{p_tenant:tenant,p_property:property,...command})}
  catch(e){if(definitiveBookingRejection(e)){sessionStorage.removeItem(storageKey);if(alive.current)setPending(null);throw e}throw Error('The booking result is uncertain. Retry the saved request below; its reference prevents a duplicate reservation.')}
  if(alive.current){sessionStorage.removeItem(storageKey);setPending(null);await onSaved(result)}
 }
 return <>{error&&<div className="pilot-error" role="alert">{error}</div>}{restoreError?<div className="pilot-error" role="alert">{restoreError}</div>:pending?<section className="pilot-settings"><h3>Resolve saved booking request</h3><div className="detail-grid"><div>Guest<b>{pending.p_guest_name}</b></div><div>Room type<b>{types.find(t=>t.id===pending.p_room_type)?.name??'Saved room type'}</b></div><div>Arrival<b>{pending.p_arrival}</b></div><div>Departure<b>{pending.p_departure}</b></div><div>Guests<b>{pending.p_guests}</b></div><div>Stay value<b>{usd(pending.p_accommodation_minor+pending.p_taxes_minor)}</b></div></div><p>Reference: {pending.p_request}</p><p>The original details are preserved until the booking result is confirmed. Retrying returns the existing booking if it was already saved.</p><button className="primary" disabled={busy} onClick={()=>void run(()=>book(pending))}>{busy?'Confirming…':'Retry this exact booking request'}</button></section>:<><button className="secondary" disabled={busy} onClick={onUseRates}>Use configured rate-plan pricing</button><form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void run(async()=>{const command:ManualBookingRequest={p_request:crypto.randomUUID(),p_room_type:formText(f,'type'),p_guest_name:formText(f,'name').trim(),p_arrival:formText(f,'arrival'),p_departure:formText(f,'departure'),p_guests:Number(f.get('guests')),p_accommodation_minor:cents(f.get('amount')),p_taxes_minor:cents(f.get('taxes'))};sessionStorage.setItem(storageKey,JSON.stringify(command));setPending(command);await book(command)})}}><label className="field">Guest name<input name="name" required maxLength={200} disabled={busy}/></label><label className="field">Room type<select name="type" required disabled={busy}>{types.map(t=><option value={t.id} key={t.id}>{t.name}</option>)}</select></label><label className="field">Guests<input name="guests" type="number" min="1" max="20" defaultValue="2" required disabled={busy}/></label><div className="form-grid"><label className="field">Arrival<input name="arrival" type="date" defaultValue={businessDate} required disabled={busy}/></label><label className="field">Departure<input name="departure" type="date" required disabled={busy}/></label></div><div className="form-grid"><label className="field">Accommodation (USD)<input name="amount" type="number" step="0.01" min="0" required disabled={busy}/></label><label className="field">Taxes (USD)<input name="taxes" type="number" step="0.01" min="0" required disabled={busy}/></label></div><p className="muted">These are manually entered amounts. Use configured rate-plan pricing above to calculate City, State and Lodging taxes, Resort fees, Technology fees, and any enabled whole-home Cleaning fee. Inventory is checked for every night. No payment is collected.</p><button className="primary full" disabled={busy}>{busy?'Saving…':'Save reservation'}</button></form></>}</>;
}
